'use strict';
const $=id=>document.getElementById(id);
const roster=[['Triceratops','A sturdy youngster finding a place in the valley.'],['Parasaurolophus','A curious youngster following new sights and sounds.'],['Velociraptor','An alert youngster exploring beyond the familiar.']];
const attributes=['health','strength','knowledge','empathy','fun'];
const objects=[{id:'tree',name:'Fruit tree',x:-2,z:10,height:400,width:340},{id:'animal',name:'Wild animal',x:3,z:13,height:240,width:320},{id:'nest',name:'Hidden haven',x:0,z:25,height:100,width:250}];
const missions=[
 {type:'Eat',title:'A first discovery',giver:'Your first instinct',copy:'You begin alone. A fruit tree stands in the clearing. Walk closer, point at it, and decide how to respond to your first discovery.',objective:'Walk to the fruit tree. Point, select, and choose an action.',target:'tree'},
 {type:'Find',title:'An unexpected neighbor',giver:'Movement in the grass',copy:'A small wild animal watches from the far side of the clearing. It is not a community member. Approach and decide whether this encounter becomes friendship, play, or a hunt.',objective:'Walk toward the wild animal. Point and choose how to interact.',target:'animal'},
 {type:'Build',title:'A hidden haven',giver:'A distant nest guardian',copy:'A dinosaur guardian calls from uphill. There is room for a new home above the river, but a storm is coming. Find the straw nest and help prepare a safer place for the eggs.',objective:'Follow the path forward to the nest. Prepare the hidden haven.',target:'nest'}
];
const decisions={
 tree:[
 {id:'eat',title:'Eat apples',stat:'health',value:20,result:'You pick a few apples and eat in the shade. Your health rises, and the red fruit disappears from the branches.',lasting:'The tree remains standing, but its fruit has been collected for this journey.'},
 {id:'destroy',title:'Destroy the tree',stat:'strength',value:10,result:'You push against the trunk until it gives way. Practicing a forceful action increases strength; a stump is left behind.',lasting:'This food source and its shade are gone. A short-term gain changes the shared habitat.'},
 {id:'name',title:'Give the tree a name',stat:'knowledge',value:5,result:'You study the tree and give this landmark a name. Its label appears in the scene, making the place easier to remember.',lasting:'The tree remains intact. The named landmark becomes part of your journey.'}
 ],
 animal:[
 {id:'friend',title:'Try to make a friend',stat:'empathy',value:20,result:'You lower your forelimbs and approach gently. The animal stays nearby; a heart marks the beginning of trust.',lasting:'This animal becomes a protected friend. The encounter supports coexistence.'},
 {id:'play',title:'Play with the animal',stat:'fun',value:10,result:'You hop and circle together. The animal answers with a playful bounce; the encounter increases fun.',lasting:'The animal remains in the clearing. Shared play creates a positive memory.'},
 {id:'attack',title:'Attack the animal',stat:'health',value:50,result:'You hunt the wild animal. The encounter restores health, but the animal disappears and only tracks remain.',lasting:'You gain sustenance and lose the opportunity for friendship with this animal.'}
 ],
 nest:[
 {id:'shelter',title:'Drag branches into shelter',stat:'strength',value:10,result:'You move fallen branches around the nest. A protective shelter appears, and the guardian brings the eggs onto higher ground.',lasting:'The haven is ready for the first storm. Natural construction strengthens the nesting site.'},
 {id:'care',title:'Line the nest with soft straw',stat:'empathy',value:20,result:'You gather soft plants and carefully line the nest. The guardian brings the eggs to their new resting place.',lasting:'The community welcomes your care. You have found a place to belong.'},
 {id:'scout',title:'Mark a dry escape route',stat:'knowledge',value:5,result:'You inspect the high ground and mark a route away from the river. A trail appears beside the nest as the guardian brings the eggs.',lasting:'The community gains a route to safety and a new haven to explore from.'}
 ]
};
const game={started:false,species:0,screen:'play',mission:0,phase:'receive',camera:{x:0,z:0},aim:null,panel:null,activeObject:null,results:[],stats:{health:40,strength:10,knowledge:0,empathy:0,fun:0},completed:new Set()};
const held=new Set();let lastTime=0,lastPointer=null,toastTimer,previousFocus=null;
function fit(){document.documentElement.style.setProperty('--fit',Math.min(innerWidth/1600,innerHeight/900));}
addEventListener('resize',fit);fit();
function svgNode(name,attrs={}){const n=document.createElementNS('http://www.w3.org/2000/svg',name);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));return n;}
function distance(id){const o=objects.find(o=>o.id===id);return Math.hypot(o.x-game.camera.x,o.z-game.camera.z);}
function project(o){const depth=o.z-game.camera.z;return {visible:depth>1,x:800+(o.x-game.camera.x)*1200/Math.max(depth,1),y:205+3000/Math.max(depth,1),scale:Math.min(2.4,12/Math.max(depth,1))};}
function resultFor(id){return game.results.find(r=>r.object===id);}
function renderWorld(){
 $('objects').replaceChildren();
 [...objects].sort((a,b)=>b.z-a.z).forEach(o=>{
  const p=project(o);if(!p.visible||p.x< -550||p.x>2150)return;
  const result=resultFor(o.id),g=svgNode('g',{class:'object'+(game.aim===o.id?' aimed':''),'data-object':o.id,role:'button',tabindex:game.started?0:-1,'aria-label':`${o.name}, ${Math.round(distance(o.id))} meters away. Select to interact.`,transform:`translate(${p.x} ${p.y}) scale(${p.scale})`});
  g.append(svgNode('ellipse',{class:'halo',cx:0,cy:-o.height/2,rx:o.width/2+20,ry:o.height/2+24}));
  let drawing=o.id==='tree'?(result?.action==='destroy'?'stumpDrawing':'treeDrawing'):o.id==='animal'?'animalDrawing':'nestDrawing';
  if(o.id==='animal'&&result?.action==='attack'){
   g.append(svgNode('path',{d:'M-35 0l10-13m11 19 9-15M20-16l8-12m10 19 8-15',stroke:'#b6a284','stroke-width':5,fill:'none'}));
  }else{
   const clone=$(drawing).cloneNode(true);clone.removeAttribute('id');
   if(o.id==='tree'&&result?.action==='eat')clone.querySelector('.fruit').setAttribute('display','none');
   if(o.id==='nest'&&!result)clone.querySelectorAll('ellipse').forEach((n,i)=>{if(i>0)n.setAttribute('display','none')});
   g.append(clone);
  }
  if(o.id==='nest'&&result){g.append(svgNode('path',{d:result.action==='scout'?'M110 0L175-20 197-48':'M-125 0L-105-90 0-155 105-90 125 0',fill:'none',stroke:result.action==='scout'?'#d3af4f':'#a47b45','stroke-width':9,'stroke-linecap':'round'}));}
  if(o.id==='animal'&&result&&result.action!=='attack'){const e=svgNode('text',{class:'effect',x:0,y:-265});e.textContent=result.action==='friend'?'♥':'♫';g.append(e);}
  const label=svgNode('text',{class:'object-name',y:o.id==='animal'?100:45});label.textContent=result?.name||(o.id==='animal'&&result?.action==='attack'?'Animal tracks':o.name);g.append(label);
  g.append(svgNode('rect',{class:'hit',x:-o.width/2-15,y:-o.height-15,width:o.width+30,height:o.height+125}));
  g.addEventListener('pointerenter',()=>aim(o.id));g.addEventListener('focus',()=>{aim(o.id);pointAt(o.id)});g.addEventListener('click',()=>{aim(o.id);pointAt(o.id);interact()});g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();aim(o.id);pointAt(o.id);interact()}});
  $('objects').append(g);
 });
 if(game.aim&&!document.querySelector(`[data-object="${game.aim}"]`))game.aim=null;
 $('coords').textContent=Math.round(game.camera.z)+' m into the valley';$('placeLabel').textContent=game.camera.z>17?'The hidden haven':'The first clearing';
 updateAim();
}
function pointAt(id){const o=objects.find(o=>o.id===id),p=project(o);drawRay(p.x,p.y-o.height*p.scale*.55);}
function drawRay(x,y){$('ray').setAttribute('d',`M415 725L${x} ${y}`);$('reticle').setAttribute('cx',x);$('reticle').setAttribute('cy',y);}
function aim(id){game.aim=id;updateAim();}
function updateAim(){document.querySelectorAll('.object').forEach(g=>g.classList.toggle('aimed',g.dataset.object===game.aim));const o=objects.find(o=>o.id===game.aim);let text='Point at the tree, animal, or distant nest.';if(o){const d=distance(o.id);text=`${o.name} · ${d.toFixed(1)} m · ${d>7.5?'Walk closer to interact':'Click or press E to interact'}`;if(game.completed.has(o.id))text=`${o.name} · Decision already recorded`;}if(game.phase==='receive'&&game.started)text='Your first mission is ready.';$('targetHint').textContent=text;$('interact').textContent='Interact / E';$('interact').disabled=!game.started||game.screen!=='play'||!!game.panel||game.phase==='receive'||!o||distance(o.id)>7.5;}
$('scene').addEventListener('pointermove',e=>{if(game.panel||game.screen!=='play')return;lastPointer={x:e.clientX,y:e.clientY};const rect=$('scene').getBoundingClientRect();drawRay((e.clientX-rect.left)*1600/rect.width,(e.clientY-rect.top)*748/rect.height);const target=e.target.closest('[data-object]');aim(target?.dataset.object||null);});
$('scene').addEventListener('pointerleave',()=>{lastPointer=null;if(!game.panel)aim(null)});
function clearMovement(){held.clear();document.querySelectorAll('[data-move]').forEach(b=>b.classList.remove('pressed'));}
function showPanel(kind,title,copy,tag='DECISION / INTERACTION'){
 clearMovement();clearTimeout(toastTimer);$('toast').hidden=true;if(!$('modal').hidden)previousFocus=previousFocus||document.activeElement;else previousFocus=document.activeElement;
 game.panel=kind;$('panelTitle').textContent=title;$('panelCopy').textContent=copy;$('panelTag').textContent=tag;$('panelBody').replaceChildren();$('panelActions').replaceChildren();$('modal').hidden=false;$('play').inert=true;updateAim();document.querySelector('.panel').focus();
}
function hidePanel(){game.panel=null;$('modal').hidden=true;$('play').inert=game.screen!=='play';updateAim();if(previousFocus?.isConnected)previousFocus.focus();previousFocus=null;}
function actionButton(label,fn,primary=true){const b=document.createElement('button');b.className=primary?'primary':'quiet';b.textContent=label;b.onclick=fn;$('panelActions').append(b);return b;}
function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
function renderHud(){attributes.forEach(k=>$(k).textContent=game.stats[k]);const m=missions[Math.min(game.mission,2)];$('missionPhase').textContent=game.phase==='free'?'JOURNEY / COMPLETE':`MISSION ${Math.min(game.mission+1,3)} / ${m.type.toUpperCase()}`;$('missionTitle').textContent=game.phase==='free'?'A place to belong.':m.title;$('missionObjective').textContent=game.phase==='free'?'Your haven is ready. Inspect your choices or restart to explore another path.':m.objective;const step={receive:0,walk:1,decide:2,feedback:3,free:3}[game.phase];document.querySelectorAll('[data-step]').forEach(n=>n.classList.toggle('current',+n.dataset.step===step));document.querySelectorAll('[data-move]').forEach(b=>b.disabled=!game.started||!!game.panel||game.screen!=='play'||game.phase==='receive');updateAim();}
function chooseSpecies(){showPanel('species','A little dinosaur. A big world.','Choose your species before your journey begins. This example roster is a proposal.','START / CHOOSE YOUR SPECIES');roster.forEach((s,i)=>{const b=document.createElement('button');b.className='choice species-card'+(game.species===i?' selected':'');b.setAttribute('aria-pressed',String(game.species===i));const title=document.createElement('span');title.textContent=s[0];const small=document.createElement('small');small.textContent=s[1];title.append(small);b.append(title);const pill=document.createElement('span');pill.className='pill';pill.textContent=game.species===i?'Selected':'Choose';b.append(pill);b.onclick=()=>{game.species=i;chooseSpecies()};$('panelBody').append(b)});actionButton('Enter the clearing →',()=>{game.started=true;hidePanel();renderWorld();missionIntro()});renderHud();}
function missionIntro(){if(game.mission>=3){game.phase='free';renderHud();return}const m=missions[game.mission];game.phase='receive';showPanel('mission',m.title,m.copy,`RECEIVE / ${m.type.toUpperCase()} MISSION`);const info=document.createElement('div');info.className='result-box';info.textContent=`From: ${m.giver}. Objective: ${m.objective}`;$('panelBody').append(info);actionButton('Accept mission · walk into the scene',()=>{hidePanel();game.phase='walk';renderHud();toast('Hold the walking arrows. Point at '+objects.find(o=>o.id===m.target).name.toLowerCase()+'.')});renderHud();}
function interact(){if(!game.started||game.screen!=='play'||game.panel)return;if(game.phase==='receive'){missionIntro();return}if(!game.aim)return;const o=objects.find(o=>o.id===game.aim);if(distance(o.id)>7.5){toast('Walk closer. '+o.name+' is '+distance(o.id).toFixed(1)+' m away.');return}if(game.completed.has(o.id)){const r=resultFor(o.id);showPanel('inspect','A choice already made.',r.result,'JOURNAL / '+o.name.toUpperCase());const box=document.createElement('div');box.className='result-box';box.textContent=r.lasting;$('panelBody').append(box);actionButton('Back to the scene',()=>{hidePanel();renderHud()});return}if(o.id!==missions[game.mission]?.target){toast('Your current mission is to investigate '+objects.find(o=>o.id===missions[game.mission].target).name.toLowerCase()+'.');return}
 game.activeObject=o.id;game.phase='decide';showPanel('decision',o.id==='tree'?'Tree selected':o.id==='animal'?'Animal selected':'Haven selected','Decision: choose an action and see how it changes you and the clearing.');
 decisions[o.id].forEach((d,i)=>{const b=document.createElement('button');b.className='choice';b.dataset.decision=d.id;const title=document.createElement('span');title.textContent=d.title;const reward=document.createElement('span');reward.className='reward '+d.stat;reward.textContent='+'+d.value+' '+d.stat;b.append(title,reward);b.onclick=()=>d.id==='name'?nameTree():resolveAction(o.id,i);$('panelBody').append(b)});
 actionButton('Leave',()=>leavePanel(),false);renderHud();
}
function nameTree(){showPanel('name','Name this landmark.','A name helps your dinosaur remember this place.','TREE / +5 KNOWLEDGE');const label=document.createElement('label');label.textContent='Tree name';label.htmlFor='treeName';const input=document.createElement('input');input.id='treeName';input.maxLength=28;input.value='First Light';$('panelBody').append(label,input);actionButton('Confirm name',()=>{const name=input.value.trim();if(!name){input.setAttribute('aria-invalid','true');input.focus();return}resolveAction('tree',2,name)});actionButton('Back',()=>{hidePanel();game.phase='walk';aim('tree');interact()},false);input.focus();input.select();input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const b=$('panelActions').querySelector('button');b.click()}});}
function resolveAction(id,index,name){if(game.panel!=='decision'&&game.panel!=='name')return;if(game.completed.has(id)||id!==missions[game.mission]?.target||distance(id)>7.5)return;const d=decisions[id][index];if(!d)return;const before=game.stats[d.stat];game.stats[d.stat]=Math.min(100,before+d.value);const gained=game.stats[d.stat]-before;game.completed.add(id);const record={object:id,action:d.id,title:d.title,result:d.result,lasting:d.lasting,stat:d.stat,value:gained,name:name||null};game.results.push(record);game.phase='feedback';renderWorld();showPanel('feedback',d.title,'Your decision has an immediate result and a lasting effect.','FEEDBACK / '+objects.find(o=>o.id===id).name.toUpperCase());const box=document.createElement('div');box.className='result-box';const strong=document.createElement('strong');strong.textContent='+'+gained+' '+d.stat+' · '+game.stats[d.stat]+'/100';const p=document.createElement('p');p.textContent=d.result;const small=document.createElement('small');small.textContent='LASTING EFFECT: '+d.lasting;box.append(strong,p,small);$('panelBody').append(box);actionButton(game.mission<2?'See the change in the clearing →':'See your hidden haven →',()=>finishFeedback(false));renderHud();renderJournal();}
function finishFeedback(){hidePanel();game.mission=Math.min(3,game.results.length);game.phase=game.mission>=3?'free':'walk';renderHud();if(game.mission<3)toast('New mission: '+missions[game.mission].title+'. '+missions[game.mission].objective);else toast('Journey complete. Your choices are recorded below the scene until you restart.');}
function cancelRestart(){if(game.phase==='feedback'){finishFeedback(false);return}hidePanel();if(!game.started)chooseSpecies();else if(game.phase==='receive')missionIntro();else{if(game.phase==='decide')game.phase='walk';renderHud();}}
function leavePanel(){if(game.panel==='feedback'){finishFeedback(false);return}if(game.panel==='species'||game.panel==='mission'){toast('Choose a species and accept your mission to begin.');return}if(game.panel==='restart'){cancelRestart();return}hidePanel();if(game.phase==='decide')game.phase='walk';renderHud();}
function move(direction,amount){if(!game.started||game.panel||game.screen!=='play'||game.phase==='receive')return;const c=game.camera;if(direction==='forward')c.z+=amount;if(direction==='back')c.z-=amount;if(direction==='left')c.x-=amount;if(direction==='right')c.x+=amount;c.x=Math.max(-8,Math.min(8,c.x));c.z=Math.max(0,Math.min(28,c.z));renderWorld();if(game.aim)pointAt(game.aim);}
document.querySelectorAll('[data-move]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();if(b.disabled)return;b.setPointerCapture(e.pointerId);held.add(b.dataset.move);b.classList.add('pressed');move(b.dataset.move,.7)});b.addEventListener('pointerup',clearMovement);b.addEventListener('pointercancel',clearMovement);b.addEventListener('lostpointercapture',clearMovement);b.addEventListener('click',e=>{if(e.detail===0)move(b.dataset.move,1)});});
const keys={w:'forward',ArrowUp:'forward',s:'back',ArrowDown:'back',a:'left',ArrowLeft:'left',d:'right',ArrowRight:'right'};
addEventListener('keydown',e=>{if(e.key==='Escape'){if(game.panel){e.preventDefault();leavePanel()}return}if(e.key==='Tab'&&game.panel){const focusables=[...$('modal').querySelectorAll('button:not(:disabled),input')];if(!focusables.length)return;const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===document.querySelector('.panel'))){last.focus();e.preventDefault()}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===document.querySelector('.panel'))){first.focus();e.preventDefault()}return}if(e.target.matches('input,textarea'))return;if(keys[e.key]&&!game.panel&&game.screen==='play'){e.preventDefault();held.add(keys[e.key]);document.querySelector(`[data-move="${keys[e.key]}"]`).classList.add('pressed')}if(e.key.toLowerCase()==='e'&&!e.repeat){e.preventDefault();interact()}});
addEventListener('keyup',e=>{if(keys[e.key]){held.delete(keys[e.key]);document.querySelector(`[data-move="${keys[e.key]}"]`).classList.remove('pressed')}});addEventListener('blur',clearMovement);document.addEventListener('visibilitychange',clearMovement);addEventListener('pointerup',clearMovement);
function animate(time){const dt=Math.min(.05,(time-lastTime)/1000||0);lastTime=time;if(held.size){const speed=4*dt/Math.sqrt(held.size);for(const dir of held)move(dir,speed);}requestAnimationFrame(animate);}requestAnimationFrame(animate);
$('interact').onclick=interact;
function renderJournal(){
 $('journalCount').textContent=game.results.length+' / 3 decisions';$('journalBody').replaceChildren();
 if(!game.results.length){const empty=document.createElement('p');empty.className='journal-empty';empty.textContent='Your decisions will leave a trace here.';$('journalBody').append(empty);return}
 game.results.forEach((r,i)=>{const row=document.createElement('div');row.className='journal-row';const title=document.createElement('span');title.textContent='0'+(i+1)+' · '+r.title+(r.name?' — '+r.name:'');title.title=r.result+' '+r.lasting;const reward=document.createElement('span');reward.className='reward '+r.stat;reward.textContent='+'+r.value+' '+r.stat;row.append(title,reward);$('journalBody').append(row)});
}

$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('Full screen is unavailable here. The 16:9 view still fits your window.')}};
document.addEventListener('fullscreenchange',()=>{$('fullscreen').textContent=document.fullscreenElement?'⛶ Exit full screen':'⛶ Full screen';fit()});
$('restart').onclick=()=>{showPanel('restart','Begin a new journey?','This clears your choices, attribute rewards, and journal.');actionButton('Restart journey',reset);actionButton('Keep exploring',cancelRestart,false);renderHud()};
function reset(){clearMovement();hidePanel();game.started=false;game.mission=0;game.phase='receive';game.camera={x:0,z:0};game.aim=null;game.activeObject=null;game.results=[];game.completed.clear();game.stats={health:40,strength:10,knowledge:0,empathy:0,fun:0};clearTimeout(toastTimer);$('toast').hidden=true;renderWorld();renderJournal();renderHud();chooseSpecies();}
renderJournal();renderWorld();chooseSpecies();
